use super::types::*;
use core::mem::{offset_of, size_of};

#[test]
fn bio_layout_matches_the_module_header_contract() { assert_eq!(size_of::<LinuxBioVec>(), 16); assert_eq!(size_of::<LinuxBio>(), 80); assert_eq!(offset_of!(LinuxBio, bi_size), 40); assert_eq!(offset_of!(LinuxBio, bi_io_vec), 48); assert_eq!(offset_of!(LinuxBio, bi_vcnt), 56); assert_eq!(offset_of!(LinuxBio, bi_end_io), 64); }
#[test]
fn block_device_layout_matches_the_supported_module_abi() { assert_eq!(size_of::<LinuxBlockDevice>(), 984); assert_eq!(offset_of!(LinuxBlockDevice, bd_disk), 16); assert_eq!(offset_of!(LinuxBlockDevice, bd_queue), 24); assert_eq!(offset_of!(LinuxBlockDevice, bd_holders), 128); assert_eq!(offset_of!(LinuxBlockDevice, bd_fsfreeze_mutex), 152); assert_eq!(offset_of!(LinuxBlockDevice, bd_device), 208); }
#[test]
fn gendisk_layout_matches_the_supported_module_abi() { assert_eq!(size_of::<LinuxGendisk>(), 656); assert_eq!(offset_of!(LinuxGendisk, part0), 64); assert_eq!(offset_of!(LinuxGendisk, queue), 80); assert_eq!(offset_of!(LinuxGendisk, flags), 344); assert_eq!(offset_of!(LinuxGendisk, state), 352); assert_eq!(offset_of!(LinuxGendisk, queue_kobj), 408); assert_eq!(offset_of!(LinuxGendisk, diskseq), 600); assert_eq!(offset_of!(LinuxGendisk, rqos_state_mutex), 624); assert_eq!(offset_of!(LinuxGendisk, zoned), 512); }
