#[test]
fn zoned_report_layout_matches_the_module_header_contract() { assert_eq!(size_of::<LinuxBlkZone>(), 64); assert_eq!(offset_of!(LinuxBlkZone, start), 0); assert_eq!(offset_of!(LinuxBlkZone, wp), 16); assert_eq!(offset_of!(LinuxBlkZone, zone_type), 24); assert_eq!(offset_of!(LinuxBlkZone, capacity), 32); assert_eq!(size_of::<LinuxBlkReportZonesArgs>(), 24); assert_eq!(offset_of!(LinuxBlkReportZonesArgs, cb), 0); assert_eq!(offset_of!(LinuxBlkReportZonesArgs, data), 8); assert_eq!(offset_of!(LinuxBlkReportZonesArgs, report_active), 16); assert_eq!(size_of::<LinuxGendiskZoned>(), 72); assert_eq!(offset_of!(LinuxGendiskZoned, zone_wplugs_hash), 48); }
